"""Card [6] 'Done when': lookup by card_token in single-digit ms, plus the card's build settings.
Read-only. Run: docker compose run --rm --no-deps setup python -m scripts.verify_store"""
import time
from collections import Counter

from common.aws import client

TABLE, N = "card_features", 500
REQUIRED = ("card_token", "txn_count_5m", "avg_amount_30d", "blocked", "updated_at")
# known_devices is optional per row: DynamoDB can't store an empty set, so a card with no
# trusted devices simply has no attribute.


def pct(xs, p):
    xs = sorted(xs)
    return xs[min(len(xs) - 1, int(len(xs) * p))]


def main():
    ddb = client("dynamodb")
    t = ddb.describe_table(TableName=TABLE)["Table"]
    hash_key = [k["AttributeName"] for k in t["KeySchema"] if k["KeyType"] == "HASH"]
    mode = t.get("BillingModeSummary", {}).get("BillingMode", "PROVISIONED")
    ttl = ddb.describe_time_to_live(TableName=TABLE)["TimeToLiveDescription"]
    try:
        pitr = ddb.describe_continuous_backups(TableName=TABLE)["ContinuousBackupsDescription"][
            "PointInTimeRecoveryDescription"]["PointInTimeRecoveryStatus"]
    except Exception as e:                                   # LocalStack may not support this call
        pitr = f"not reported here ({type(e).__name__})"
    sse = t.get("SSEDescription", {}).get("Status", "default AWS-owned key")  # absent = default encryption

    rows = ddb.scan(TableName=TABLE, Limit=50)["Items"]
    if not rows:
        raise SystemExit("card_features is empty: run scripts/smoke.py or a replay first")
    missing = Counter(f for r in rows for f in REQUIRED if f not in r)
    with_devices = sum("known_devices" in r for r in rows)
    tokens = [r["card_token"]["S"] for r in rows]

    for tok in tokens[:10]:                                  # warm-up: first calls open the connection
        ddb.get_item(TableName=TABLE, Key={"card_token": {"S": tok}})
    ms = []
    for i in range(N):
        t0 = time.perf_counter()
        ddb.get_item(TableName=TABLE, Key={"card_token": {"S": tokens[i % len(tokens)]}})
        ms.append((time.perf_counter() - t0) * 1000)
    p50, p95, p99 = pct(ms, 0.50), pct(ms, 0.95), pct(ms, 0.99)

    print(f"lookups: {N}   p50 {p50:.1f} ms   p95 {p95:.1f} ms   p99 {p99:.1f} ms   max {max(ms):.1f} ms")
    print(f"rows sampled: {len(rows)}   missing attributes: {dict(missing) or 'none'}   "
          f"rows with known_devices: {with_devices}")
    print(f"info: encryption = {sse}   PITR = {pitr}")
    checks = [("partition key is card_token", hash_key == ["card_token"]),
              (f"on-demand capacity (got {mode})", mode == "PAY_PER_REQUEST"),
              (f"TTL on expires_at (got {ttl.get('TimeToLiveStatus')} / {ttl.get('AttributeName')})",
               ttl.get("TimeToLiveStatus") == "ENABLED" and ttl.get("AttributeName") == "expires_at"),
              ("every row has the required card attributes", not missing),
              ("p50 lookup in single-digit ms", p50 < 10),
              ("p95 lookup in single-digit ms", p95 < 10)]
    for name, ok in checks:
        print(("PASS " if ok else "FAIL ") + name)


if __name__ == "__main__":
    main()
